  if(state.view==='feed'&&!state.project){$('#page-title').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('#page-subtitle').textContent=state.projects.length+' 个项目 · '+active.filter(e=>!isRead(e)).length+' 件有效未读';$('#project-overview').insertAdjacentHTML('afterend',overview())}
  $('.top-actions').insertAdjacentHTML('beforeend',`<label id="reader-language"><input type="checkbox" id="original-first" ${originalFirst?'checked':''}> 原文优先</label>`);
  const failed=liveError||liveData?.intelligence?.calendar?.status==='error'||Object.values(liveData?.sources||{}).some(v=>Object.values(v).some(s=>s.status==='error'));$('.right-column').insertAdjacentHTML('afterbegin',`<button id="reader-health" class="health-button ${failed?'warning':''}" data-reader-health>${failed?'● 部分来源需要关注':'● 采集运行中'} <span>查看状态</span></button>`);
  document.querySelectorAll('#projects .project-button').forEach(b=>{const m=liveData?.markets[b.dataset.project];if(m?.change24h!=null)b.querySelector('.project-label > span').textContent=catalog.find(p=>p.id===b.dataset.project).symbol+'  '+pct(m.change24h)});
